import json,glob
rules=[]
for p in glob.glob('/work/pricing/current/*.json'):
 for r in json.load(open(p)):
  if r['card_scheme']=='GlobalCard' and (not r['account_type'] or 'R' in r['account_type']) and (not r['merchant_category_code'] or 5942 in r['merchant_category_code']):
   rules.append((r,p))
fees=[r['fixed_amount']+r['rate']*12.75/10000 for r,p in rules]
print(len(rules))
for r,p in rules: print(r['ID'],r['account_type'],r['merchant_category_code'],r['fixed_amount'],r['rate'],r['fixed_amount']+r['rate']*12.75/10000)
print(sum(fees)/len(fees),f'{sum(fees)/len(fees):.6f}')
