import csv, json
from decimal import Decimal
from html import escape
from pathlib import Path

ROOT = Path('/work')
OUT = Path('/scratch/reports')
merchant_name = 'Belles_cookbook_store'
with open(ROOT / 'merchant_data.json', encoding='utf-8') as f:
    merchants = json.load(f)
merchant = next(x for x in merchants if x['merchant'] == merchant_name)
with open(ROOT / 'fees.json', encoding='utf-8') as f:
    rules = json.load(f)
with open(ROOT / 'payments.csv', encoding='utf-8', newline='') as f:
    payments = [r for r in csv.DictReader(f) if r['merchant'] == merchant_name and r['year'] == '2023' and 1 <= int(r['day_of_year']) <= 31]

# Natural-month volume/fraud metrics use all January transactions, not only transactions ultimately matched by a given rule.
monthly_volume = sum((Decimal(r['eur_amount']) for r in payments), Decimal(0))
monthly_fraud_amount = sum((Decimal(r['eur_amount']) for r in payments if r['has_fraudulent_dispute'] == 'True'), Decimal(0))
monthly_fraud_pct = Decimal(100) * monthly_fraud_amount / monthly_volume if monthly_volume else Decimal(0)

def matches_month_range(value, constraint):
    if constraint is None:
        return True
    if constraint == '<100k': return value < Decimal(100000)
    if constraint == '100k-1m': return Decimal(100000) <= value <= Decimal(1000000)
    if constraint == '1m-5m': return Decimal(1000000) <= value <= Decimal(5000000)
    if constraint == '>5m': return value > Decimal(5000000)
    if constraint == '<7.2%': return monthly_fraud_pct < Decimal('7.2')
    if constraint == '7.2%-7.7%': return Decimal('7.2') <= monthly_fraud_pct <= Decimal('7.7')
    if constraint == '7.7%-8.3%': return Decimal('7.7') <= monthly_fraud_pct <= Decimal('8.3')
    if constraint == '>8.3%': return monthly_fraud_pct > Decimal('8.3')
    raise ValueError(f'Unknown range: {constraint}')

def matches_capture(rule_delay):
    if rule_delay is None: return True
    merchant_delay = merchant['capture_delay']
    if rule_delay in ('immediate', 'manual'):
        return merchant_delay == rule_delay
    days = Decimal(merchant_delay)
    if rule_delay == '<3': return days < 3
    if rule_delay == '3-5': return Decimal(3) <= days <= Decimal(5)
    if rule_delay == '>5': return days > 5
    raise ValueError(f'Unknown capture delay: {rule_delay}')

def rule_matches(rule, tx):
    if rule['card_scheme'] != tx['card_scheme']:
        return False
    for key, value in (('account_type', merchant['account_type']), ('merchant_category_code', merchant['merchant_category_code']), ('aci', tx['aci'])):
        restriction = rule[key]
        if restriction and value not in restriction: # empty lists impose no restriction
            return False
    if not matches_capture(rule['capture_delay']):
        return False
    if not matches_month_range(monthly_volume, rule['monthly_volume']):
        return False
    if not matches_month_range(monthly_fraud_pct, rule['monthly_fraud_level']):
        return False
    if rule['is_credit'] is not None and (tx['is_credit'] == 'True') != rule['is_credit']:
        return False
    if rule['intracountry'] is not None and (tx['issuing_country'] == tx['acquirer_country']) != bool(rule['intracountry']):
        return False
    return True

aggregated = {}
for rule in rules:
    matches = [tx for tx in payments if rule_matches(rule, tx)]
    if not matches:
        continue
    amount = sum((Decimal(tx['eur_amount']) for tx in matches), Decimal(0))
    fee = sum((Decimal(str(rule['fixed_amount'])) + Decimal(rule['rate']) * Decimal(tx['eur_amount']) / Decimal(10000) for tx in matches), Decimal(0))
    aggregated[rule['ID']] = {
        'fee_id': rule['ID'],
        'card_scheme': rule['card_scheme'],
        'transactions': len(matches),
        'amount_eur': amount,
        'fee_eur': fee,
    }
rows = [aggregated[key] for key in sorted(aggregated)]

csv_path = OUT / '5.csv'
with open(csv_path, 'w', newline='', encoding='utf-8') as f:
    writer = csv.DictWriter(f, fieldnames=['fee_id', 'card_scheme', 'transactions', 'amount_eur', 'fee_eur'])
    writer.writeheader()
    for row in rows:
        writer.writerow({
            'fee_id': row['fee_id'],
            'card_scheme': row['card_scheme'],
            'transactions': row['transactions'],
            'amount_eur': f"{row['amount_eur']:.2f}",
